"""Create a standalone, offline HTML preview of the planned 320-playbook library."""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
content=(ROOT/'data/playbooks.json').read_text(encoding='utf8').replace('</script','<\\/script')
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WDS USA | 320 SEO Playbook Preview</title><style>
:root{font-family:Inter,system-ui,-apple-system,Segoe UI,Arial,sans-serif;color:#142441;background:#f5f8fd}*{box-sizing:border-box}body{margin:0}a{color:inherit;text-decoration:none}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #7aa7ff;outline-offset:3px}.wrap{max-width:1260px;margin:0 auto;padding:0 28px}.top{background:#101c35;color:#e6edfc}.nav{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:18px 0}.brand{font-size:19px;font-weight:850;letter-spacing:-.05em}.brand i{display:inline-grid;width:32px;height:32px;place-items:center;background:#4385ee;border-radius:8px;color:white;font-style:normal;margin-right:9px}.navlinks{display:flex;gap:25px;color:#aebbd4;font-size:13px;font-weight:700}.pill{border:1px solid #52627d;padding:9px 13px;border-radius:30px;font-size:12px;color:#c9d7f5}.hero{background:radial-gradient(circle at 80% 25%,#2a4e9c 0,transparent 43%),#101c35;color:white;padding:62px 0 72px}.hero small{color:#9ab9fb;letter-spacing:.18em;font-weight:800;font-size:11px}.hero h1{font-size:clamp(40px,5vw,66px);max-width:800px;line-height:1.09;letter-spacing:-.07em;margin:21px 0}.hero h1 em{font-family:Georgia,serif;color:#8fb3ff;font-weight:400}.hero p{font-size:17px;line-height:1.7;color:#b9c5dd;max-width:710px}.stats{display:flex;gap:28px;flex-wrap:wrap;margin-top:33px}.stats span{display:flex;align-items:baseline;gap:7px;font-size:12px;color:#aec0dc}.stats strong{font-size:24px;color:white}.preview-note{background:#e8f0ff;color:#2d538c;padding:13px 0;font-size:12px;line-height:1.5}.area{display:grid;grid-template-columns:275px minmax(0,1fr);gap:28px;padding-top:48px;padding-bottom:80px}.aside{position:sticky;top:20px;align-self:start;background:white;border:1px solid #e3eaf4;border-radius:15px;padding:18px;max-height:calc(100vh - 30px);overflow:auto}.aside h2{font-size:15px;color:#152847;margin:6px 9px 13px}.topics{display:grid;gap:3px}.topics button{text-align:left;border:0;background:transparent;color:#526781;padding:11px 10px;border-radius:8px;font-weight:650;font-size:12px;line-height:1.4}.topics button:hover,.topics button.active{background:#edf3ff;color:#235fbe}.topics small{font-weight:500;color:#92a0b6;float:right}.main{min-width:0}.head{display:flex;align-items:start;justify-content:space-between;gap:20px;margin:0 0 23px}.head h2{font-size:29px;line-height:1.2;letter-spacing:-.045em;margin:4px 0 10px}.head p{color:#74839b;margin:0;line-height:1.6}.search{border:1px solid #dce6f3;border-radius:10px;padding:14px 16px;min-width:265px;background:white}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.card{border:1px solid #e1e8f2;background:#fff;border-radius:14px;text-align:left;padding:23px;min-height:165px;display:flex;flex-direction:column;gap:10px;box-shadow:0 5px 24px #152f5b08}.card:hover{border-color:#78a5ea;box-shadow:0 10px 32px #1b4e9912}.card small{text-transform:uppercase;color:#3872bf;font-weight:850;font-size:10px;letter-spacing:.07em}.card strong{font-size:18px;letter-spacing:-.03em;line-height:1.3}.card span{font-size:12px;color:#70809b;line-height:1.55}.card label{color:#215ebc;font-size:12px;font-weight:800;margin-top:auto}.details{background:#fff;border:1px solid #dce7f3;border-radius:18px;padding:30px;margin-bottom:20px;box-shadow:0 15px 35px #152f5b0b}.details button.back{border:0;color:#2064ba;background:#edf3ff;border-radius:8px;padding:10px 14px;font-size:12px;font-weight:800}.details h2{font-size:38px;letter-spacing:-.055em;line-height:1.1;margin:26px 0 14px}.details>p{font-size:16px;line-height:1.7;color:#576b89}.details h3{margin:30px 0 12px}.action{display:flex;gap:20px;align-items:start;border-top:1px solid #e8eef6;padding:20px 0}.action b{border-radius:8px;background:#eaf2ff;padding:9px 12px;color:#2770d0;font-size:12px}.action p{margin:3px 0;line-height:1.55;color:#263c5a}.callouts{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin-top:15px}.callouts>div{border-radius:12px;padding:18px;background:#fff5e9;border:1px solid #f1deca}.callouts>div:last-child{background:#eaf8f2;border-color:#d0e9dd}.callouts small{display:block;font-weight:800;margin-bottom:7px}.callouts p{margin:0;color:#596b7c;font-size:13px;line-height:1.65}.url{font-size:11px!important;color:#3b71c9!important;word-break:break-all}.end{background:#101c35;color:#98adca;padding:26px 0;font-size:13px}.end a{color:white}.none{padding:28px;border:1px dashed #bbcae0;border-radius:12px;color:#70809b}@media(max-width:960px){.area{grid-template-columns:1fr}.aside{position:static;max-height:none}.topics{grid-template-columns:repeat(3,1fr)}.cards{grid-template-columns:1fr 1fr}}@media(max-width:640px){.wrap{padding:0 17px}.navlinks{display:none}.hero{padding:45px 0}.area{gap:20px}.topics{grid-template-columns:repeat(2,1fr)}.cards,.callouts{grid-template-columns:1fr}.head{flex-direction:column}.search{width:100%;min-width:0}.details h2{font-size:30px}}
</style></head><body><div class="top"><div class="wrap nav"><div class="brand"><i>W</i>WDS USA</div><div class="navlinks"><span>Services</span><span>Industries</span><span>Insights</span><span>Playbooks</span></div><span class="pill">LOCAL DESIGN PREVIEW</span></div></div><header class="hero"><div class="wrap"><small>WEB DEVELOPMENT SERVICE USA / RESOURCE LIBRARY</small><h1>Useful web expertise. <em>Organized for action.</em></h1><p>Browse 320 topic-specific implementation checklists across 16 categories. Each has a unique objective, three checks, a known pitfall, and an acceptance test.</p><div class="stats"><span><strong>320</strong> playbooks</span><span><strong>16</strong> topic hubs</span><span><strong>363</strong> planned public routes</span></div></div></header><div class="preview-note"><div class="wrap"><strong>Preview only:</strong> This is an offline sample of the React/Next.js project. These routes will only be available on your actual domain after deploying the source code; search indexing is not guaranteed. Review all content before publication.</div></div><div class="wrap area"><aside class="aside"><h2>Choose a topic</h2><div class="topics" id="topics"></div></aside><main class="main"><div class="head"><div><h2 id="listingTitle">All playbooks</h2><p id="listingIntro">Browse by topic or search a website task.</p></div><input class="search" id="search" type="search" placeholder="Search 320 checklists…" aria-label="Search playbooks"></div><div id="detail"></div><div id="cards" class="cards"></div><p id="empty" class="none" hidden>No guides match this filter.</p></main></div><footer class="end"><div class="wrap">Preview of webdevelopmentserviceusa.com · Developed by <a href="https://www.tantsoft.com/" target="_blank" rel="noopener noreferrer">Tantsoft</a></div></footer><script id="data" type="application/json">__DATA__</script><script>
const content=JSON.parse(document.getElementById('data').textContent);const topics=content.pillars, guides=content.guides;const bySlug=Object.fromEntries(topics.map(x=>[x.slug,x]));let selected='all', current=null;const $=id=>document.getElementById(id);const node=(t,cn,text)=>{const x=document.createElement(t);if(cn)x.className=cn;if(text!==undefined)x.textContent=text;return x};
function renderTopics(){const root=$('topics');root.replaceChildren();for(const x of [{slug:'all',title:'All categories'},...topics]){const b=node('button',selected===x.slug?'active':'',x.title);const count=x.slug==='all'?guides.length:guides.filter(z=>z.pillar===x.slug).length;const c=node('small','',count);b.append(c);b.addEventListener('click',()=>{selected=x.slug;current=null;$('search').value='';render()});root.append(b)}}
function showGuide(g){current=g;render();window.scrollTo({top:310,behavior:'smooth'})}
function renderDetail(){const el=$('detail');el.replaceChildren();if(!current)return;const box=node('article','details');const back=node('button','back','← Back to guide library');back.onclick=()=>{current=null;render()};box.append(back,node('h2','',current.title),node('p','',current.goal),node('p','url','https://webdevelopmentserviceusa.com/playbooks/'+current.pillar+'/'+current.slug),node('h3','','Implementation checkpoints'));[current.step1,current.step2,current.step3].forEach((v,i)=>{const r=node('div','action');r.append(node('b','',String(i+1).padStart(2,'0')),node('p','',v));box.append(r)});const flags=node('div','callouts');for(const [label,text] of [['WATCH OUT FOR',current.pitfall],['ACCEPTANCE TEST',current.verification]]){const c=node('div');c.append(node('small','',label),node('p','',text));flags.append(c)}box.append(flags);el.append(box)}
function render(){renderTopics();renderDetail();const t=bySlug[selected],search=$('search').value.toLowerCase().trim();$('listingTitle').textContent=current?'Guide preview':t?t.title:'All playbooks';$('listingIntro').textContent=current?'Explore the editable Next.js project for the live implementation.':t?t.summary:'Select a category or search for the task you want to complete.';const pool=guides.filter(g=>(selected==='all'||g.pillar===selected)&&(!search||[g.title,g.goal,g.step1,g.step2,g.step3].some(v=>v.toLowerCase().includes(search))));$('cards').replaceChildren();$('cards').hidden=!!current;$('empty').hidden=pool.length!==0||!!current;if(current)return;for(const g of pool){const card=node('button','card');card.append(node('small','',bySlug[g.pillar].title),node('strong','',g.title),node('span','',g.goal),node('label','','View checklist →'));card.addEventListener('click',()=>showGuide(g));$('cards').append(card)}}$('search').addEventListener('input',()=>{current=null;render()});render();
</script></body></html>'''
html=html.replace('__DATA__',content)
(ROOT/'preview-playbooks.html').write_text(html,encoding='utf8')
print(f'Created {len(html):,}-byte offline preview')
